import sys
from multiprocessing import Pool, cpu_count


def make(d):
    if d:
        d -= 1
        return (make(d), make(d))
    return (None, None)


def check(t):
    l, r = t
    if l is None:
        return 1
    return 1 + check(l) + check(r)


def work(args):
    d, count = args
    total = 0
    for _ in range(count):
        total += check(make(d))
    return d, total


def main():
    n = int(sys.argv[1])
    min_depth = 4
    max_depth = max(min_depth + 2, n)
    stretch = max_depth + 1

    out = []
    print("stretch tree of depth %d\t check: %d" % (stretch, check(make(stretch))))

    long_lived = make(max_depth)

    tasks = []
    iters_by_depth = {}
    for d in range(min_depth, max_depth + 1, 2):
        iters = 1 << (max_depth - d + min_depth)
        iters_by_depth[d] = iters
        chunk = max(1, (1 << 18) >> (d + 1))
        rem = iters
        while rem > 0:
            c = min(chunk, rem)
            tasks.append((d, c))
            rem -= c

    # largest trees first for better balance
    tasks.sort(key=lambda t: -t[0])
    sums = {d: 0 for d in iters_by_depth}
    ncpu = cpu_count() or 1
    if ncpu > 1 and len(tasks) > 1:
        with Pool(ncpu) as p:
            for d, tot in p.imap_unordered(work, tasks, chunksize=1):
                sums[d] += tot
